var baseUrl = "/api/discover?tab=小说&genre_type=0&page={{page}}";
// 男频/女频通用参数处理
function getUrl(type, gender, bdtype) {
var params = "&gender=" + gender;
if (bdtype) {
params += "&bdtype=" + bdtype + "&is_ranking=1";
} else {
params += "&type=" + type;
}
return baseUrl + params;
}

